import pytest

from gcs import INTUBATED, GCS, compute_gcs


class TestBoundaries:
    def test_all_min_gives_3_severe(self):
        gcs = GCS(eye=1, verbal=1, motor=1)
        assert gcs.total == 3
        assert gcs.severity == "severe"

    def test_all_max_gives_15_mild(self):
        gcs = GCS(eye=4, verbal=5, motor=6)
        assert gcs.total == 15
        assert gcs.severity == "mild"

    def test_total_8_is_severe(self):
        gcs = GCS(eye=2, verbal=2, motor=4)
        assert gcs.total == 8
        assert gcs.severity == "severe"

    def test_total_9_is_moderate(self):
        gcs = GCS(eye=2, verbal=3, motor=4)
        assert gcs.total == 9
        assert gcs.severity == "moderate"

    def test_total_12_is_moderate(self):
        gcs = GCS(eye=3, verbal=4, motor=5)
        assert gcs.total == 12
        assert gcs.severity == "moderate"

    def test_total_13_is_mild(self):
        gcs = GCS(eye=4, verbal=4, motor=5)
        assert gcs.total == 13
        assert gcs.severity == "mild"


class TestIntubatedPathway:
    def test_t_pathway_produces_7T(self):
        gcs = GCS(eye=2, verbal=INTUBATED, motor=4)
        assert gcs.total == "7T"
        assert gcs.intubated is True

    def test_severity_rejected_for_intubated(self):
        gcs = GCS(eye=2, verbal=INTUBATED, motor=4)
        with pytest.raises(ValueError):
            gcs.severity


class TestInvalidInputs:
    def test_eye_zero_rejected_by_name(self):
        with pytest.raises(ValueError, match="eye"):
            GCS(eye=0, verbal=3, motor=4)

    def test_motor_out_of_range_rejected_by_name(self):
        with pytest.raises(ValueError, match="motor"):
            GCS(eye=3, verbal=3, motor=7)

    def test_float_verbal_rejected_by_name(self):
        with pytest.raises(ValueError, match="verbal"):
            GCS(eye=3, verbal=3.0, motor=4)

    def test_verbal_out_of_range_high_rejected_by_name(self):
        with pytest.raises(ValueError, match="verbal"):
            GCS(eye=3, verbal=6, motor=4)

    def test_string_eye_rejected_by_name(self):
        with pytest.raises(ValueError, match="eye"):
            GCS(eye="3", verbal=3, motor=4)

    def test_bool_rejected_as_non_integer(self):
        with pytest.raises(ValueError, match="motor"):
            GCS(eye=3, verbal=3, motor=True)


class TestFunctionalAPI:
    def test_compute_gcs_normal(self):
        assert compute_gcs(4, 5, 6) == (15, "mild")

    def test_compute_gcs_intubated(self):
        total, severity = compute_gcs(2, INTUBATED, 4)
        assert total == "7T"

